async function validateDocumentLink(req,b){
  let linkedLead=null;if(b.leadId){linkedLead=await one('SELECT * FROM leads WHERE id=$1',[b.leadId]);if(!linkedLead||!canOperateLead(req.broker,linkedLead))return 'Lead is outside your writable scope';}
  if(b.contactId){const params=[b.contactId],scope=contactScopeSql('c',req.broker,params),contact=await one(`SELECT c.id FROM contacts c WHERE c.id=$1 AND (${scope.clause})`,scope.params);if(!contact)return 'Contact is outside your permitted scope';if(linkedLead&&linkedLead.contactId!==b.contactId)return 'Contact does not belong to the linked lead';}
  if(b.listingId&&!await one('SELECT id FROM listings WHERE id=$1 AND deleted_at IS NULL',[b.listingId]))return 'Listing not found';
  if(b.activityId&&!await one('SELECT id FROM activities WHERE id=$1',[b.activityId]))return 'Activity not found';
  if(b.channelId){const channel=await one('SELECT contact_id FROM contact_channels WHERE id=$1',[b.channelId]);if(!channel)return 'Contact channel not found';const params=[channel.contactId],scope=contactScopeSql('c',req.broker,params);if(!await one(`SELECT c.id FROM contacts c WHERE c.id=$1 AND (${scope.clause})`,scope.params))return 'Contact channel is outside your permitted scope';}
  if(b.proposalId){const proposal=await one('SELECT p.id,l.* FROM proposals p JOIN leads l ON l.id=p.lead_id WHERE p.id=$1',[b.proposalId]);if(!proposal||!canOperateLead(req.broker,proposal))return 'Proposal is outside your writable scope';}
  return null;
}
async function canAccessDocument(req,doc){
  const complianceCases=await many(`SELECT DISTINCT o.id,o.owner_id,o.created_by,o.assigned_team_id,i.responsible_agent_id,
      COALESCE(array_agg(p.broker_id) FILTER(WHERE p.active=TRUE),ARRAY[]::uuid[]) AS participant_ids
    FROM document_versions dv
    JOIN document_compliance_evidence_versions ce ON ce.document_version_id=dv.id
    JOIN deal_document_requirement_instances i ON i.id=ce.requirement_instance_id JOIN deals d ON d.id=i.deal_id
    JOIN opportunities o ON o.id=d.opportunity_id LEFT JOIN opportunity_participants p ON p.opportunity_id=o.id
    WHERE dv.document_id=$1 GROUP BY o.id,i.responsible_agent_id
    UNION
    SELECT DISTINCT o.id,o.owner_id,o.created_by,o.assigned_team_id,i.responsible_agent_id,
      COALESCE(array_agg(p.broker_id) FILTER(WHERE p.active=TRUE),ARRAY[]::uuid[]) AS participant_ids
    FROM document_versions dv JOIN official_document_evidence_versions oe ON oe.document_version_id=dv.id
    JOIN document_compliance_official_evidence_links ol ON ol.official_evidence_id=oe.id
    JOIN deal_document_requirement_instances i ON i.id=ol.requirement_instance_id JOIN deals d ON d.id=i.deal_id
    JOIN opportunities o ON o.id=d.opportunity_id LEFT JOIN opportunity_participants p ON p.opportunity_id=o.id
    WHERE dv.document_id=$1 GROUP BY o.id,i.responsible_agent_id`,[doc.id]);
  if(complianceCases.length)return complianceCases.some(item=>item.responsibleAgentId===req.broker.id||canReadOpportunity(req.broker,item));
  if(doc.accessClassification==='restricted'&&doc.ownerId!==req.broker.id&&!isManager(req.broker))return false;
  if(doc.ownerId===req.broker.id||req.broker.role==='admin')return true;
  const leads=await many(`SELECT DISTINCT l.* FROM document_links dl JOIN leads l ON
    (dl.entity_type='Lead' AND l.id=dl.entity_id) OR (dl.entity_type='Proposal' AND EXISTS(SELECT 1 FROM proposals p WHERE p.id=dl.entity_id AND p.lead_id=l.id))
    WHERE dl.document_id=$1`,[doc.id]);if(leads.some(x=>canReadLead(req.broker,x)))return true;
  const contacts=await many(`SELECT DISTINCT c.id FROM document_links dl LEFT JOIN contact_channels ch ON dl.entity_type='ContactChannel' AND ch.id=dl.entity_id
    JOIN contacts c ON (dl.entity_type='Contact' AND c.id=dl.entity_id) OR (dl.entity_type='ContactChannel' AND c.id=ch.contact_id) WHERE dl.document_id=$1`,[doc.id]);for(const contact of contacts){const params=[contact.id],scope=contactScopeSql('c',req.broker,params);if(await one(`SELECT c.id FROM contacts c WHERE c.id=$1 AND (${scope.clause})`,scope.params))return true;}return false;
}
