r.post('/crm/proposal-versions/:versionId/review',async(req,res)=>{if(!isProposalApprover(req.broker))return res.status(403).json({error:'Team Manager or Managing Director review required'});if(req.body?.reviewConfirmation!==true)return res.status(400).json({error:'Confirm that the exact PDF was reviewed on screen before approval'});const comment=clean(req.body?.comment);const current=await one(`SELECT v.*,l.assigned_to,l.assigned_team_id,l.created_by AS lead_created_by FROM proposal_versions v JOIN proposals p ON p.id=v.proposal_id JOIN leads l ON l.id=p.lead_id WHERE v.id=$1`,[req.params.versionId]);if(!current)return res.status(404).json({error:'Proposal version not found'});if(!canApproveProposal(req.broker,{assignedTo:current.assignedTo,assignedTeamId:current.assignedTeamId,createdBy:current.leadCreatedBy}))return res.status(403).json({error:'Proposal is outside your approval scope'});const row=await transaction(async client=>{const reviewed=await one("UPDATE proposal_versions SET status='reviewed',reviewed_by=$1,reviewed_at=NOW(),review_decision='approved',review_comment=$2 WHERE id=$3 AND status='generated' RETURNING *",[req.broker.id,comment||null,current.id],client);if(!reviewed)return null;await execute("UPDATE proposals SET status='reviewed',updated_at=NOW() WHERE id=$1",[reviewed.proposalId],client);await execute("UPDATE document_versions SET status='reviewed',acknowledged_at=NOW(),immutable=1 WHERE id=$1",[reviewed.documentVersionId],client);await audit('ProposalVersion',reviewed.id,'reviewed',req.broker.id,{reviewMethod:'onscreen_pdf',comment},client);return reviewed;});if(!row)return res.status(409).json({error:'Only a generated version can be reviewed'});res.json(row);});
r.post('/crm/proposal-versions/:versionId/send',async(req,res)=>{const recipient=clean(req.body?.recipient),channel=clean(req.body?.deliveryChannel);if(!recipient||!channel)return res.status(400).json({error:'recipient and deliveryChannel are required'});const scoped=await one(`SELECT v.id,l.assigned_to,l.assigned_team_id,l.created_by AS lead_created_by FROM proposal_versions v JOIN proposals p ON p.id=v.proposal_id JOIN leads l ON l.id=p.lead_id WHERE v.id=$1`,[req.params.versionId]);if(!scoped)return res.status(404).json({error:'Proposal version not found'});if(!canOperateLead(req.broker,{assignedTo:scoped.assignedTo,assignedTeamId:scoped.assignedTeamId,createdBy:scoped.leadCreatedBy}))return res.status(403).json({error:'Proposal is outside your writable scope'});const row=await transaction(async client=>{const current=await one('SELECT * FROM proposal_versions WHERE id=$1 FOR UPDATE',[req.params.versionId],client);if(!current||current.status!=='reviewed')return null;const sent=await one("UPDATE proposal_versions SET status='sent',sent_by=$1,sent_at=NOW(),delivery_channel=$2,delivery_recipient=$3 WHERE id=$4 RETURNING *",[req.broker.id,channel,recipient,current.id],client);await execute("UPDATE proposals SET status='sent',updated_at=NOW() WHERE id=$1",[sent.proposalId],client);await execute("UPDATE document_versions SET status='sent',sent_at=NOW(),recipient=$1,immutable=1 WHERE id=$2",[recipient,sent.documentVersionId],client);await audit('ProposalVersion',sent.id,'sent',req.broker.id,{channel,recipient},client);return sent;});if(!row)return res.status(409).json({error:'Only a reviewed version can be sent'});res.json(row);});

r.post('/crm/proposal-versions/:versionId/request-changes',async(req,res)=>{
  if(!isProposalApprover(req.broker))return res.status(403).json({error:'Team Manager or Managing Director review required'});
  const reason=clean(req.body?.reason);if(reason.length<10)return res.status(400).json({error:'A meaningful change-request reason of at least 10 characters is required'});
  const current=await one(`SELECT v.*,p.proposal_number,p.title,l.id AS lead_id,l.contact_id,l.assigned_to,l.assigned_team_id,l.created_by AS lead_created_by
    FROM proposal_versions v JOIN proposals p ON p.id=v.proposal_id JOIN leads l ON l.id=p.lead_id WHERE v.id=$1`,[req.params.versionId]);
  if(!current)return res.status(404).json({error:'Proposal version not found'});
  if(!canApproveProposal(req.broker,{assignedTo:current.assignedTo,assignedTeamId:current.assignedTeamId,createdBy:current.leadCreatedBy}))return res.status(403).json({error:'Proposal is outside your approval scope'});
  const row=await transaction(async client=>{
    const returned=await one("UPDATE proposal_versions SET status='changes_requested',reviewed_by=$1,reviewed_at=NOW(),review_decision='changes_requested',review_comment=$2 WHERE id=$3 AND status='generated' RETURNING *",[req.broker.id,reason,current.id],client);
    if(!returned)return null;
    await execute("UPDATE proposals SET status='changes_requested',updated_at=NOW() WHERE id=$1",[returned.proposalId],client);
    await execute(`INSERT INTO tasks(id,lead_id,contact_id,subject,details,assignee_id,priority,due_at,created_by,task_type,proposal_id,proposal_version_id)
      VALUES($1,$2,$3,$4,$5,$6,'urgent',NOW()+INTERVAL '1 day',$7,'proposal_correction',$8,$9)`,[uuid(),current.leadId,current.contactId,`Revise ${current.proposalNumber} · Version ${current.versionNumber}`,reason,current.createdBy,req.broker.id,current.proposalId,current.id],client);
    await audit('ProposalVersion',returned.id,'changes_requested',req.broker.id,{reason,returnedTo:current.createdBy,taskCreated:true},client);
    return returned;
  });
  if(!row)return res.status(409).json({error:'Only a generated version awaiting review can be returned for changes'});
  res.json({...row,returnedTo:current.createdBy,taskCreated:true});
});

export default r;
